pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DnGmxBatchingManager} from "../src/DnGmxBatchingManager.sol";

contract InvMutTest is Test {
    DnGmxBatchingManager c;

    function setUp() public { c = new DnGmxBatchingManager(); }

    function testFuzz_property(address caller, address newKeeper) public {

        address owner = address(this);

        address before = c.keeper();

        bool ok;
        vm.prank(caller);
        try c.setKeeper(newKeeper) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok == (caller == owner));
    }
}
